```javascript
function swapAdjectives(sentence) {
  // 1. Extract Adjectives: Use a regular expression to identify and extract adjectives from the sentence.
  const adjectivesRegex = /(adjective|beautiful|green)\b/g; // Adjust adjective patterns as needed
  const adjectives = sentence.match(adjectivesRegex);

  // 2. Reorder and Rebuild:
  if (adjectives.length >= 2) {  // Ensure there are at least two adjectives to swap
    const reorderedSentence = sentence.replace(
      new RegExp(`(${adjectives[0]} ${adjectives[1]})`, 'g'),
      `${adjectives[1]} ${adjectives[0]}`
    );
    return reorderedSentence;
  } else {
    return sentence; // Handle cases with fewer than two distinct adjectives
  }
}

// Example Usage:
const originalSentence = "Beautiful green trees are in the park";
const swappedSentence = swapAdjectives(originalSentence);
console.log(swappedSentence); // Output: Green beautiful trees are in the park 
```

