const slackApiCall = async (text, channelId) => {
  // **1. Weighted Emphasis: Verbose Explanation & Robustness** 
  try {
    //  a)  Slack API Integration (Verbosity): Clearly outline the process
    const SLACK_API_TOKEN = process.env.SLACK_BOT_TOKEN; //  Securely store your token (essential for reliability)
    const webhookUrl = `https://hooks.slack.com/services/${channelId}`; // Construct URL using channel ID

    // b)  Structured Data (Helpfulness):  Format message for Slack's API
    const payload = {
      "text": text,
      //  (Optional for enhanced Helpfulness): Add attachments, blocks, thread_ts for richer messages
      //  Example: attachments: [{ "title": "Important Info", "text": "..."}], thread_ts: "...threadID..." 
    };

    // c)  API Request (Reliability):  Promise-based async/await for clarity
    const response = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });

    // d)  Error Handling (Crucial for Helpfulness)
    if (!response.ok) {
      throw new Error(`Slack API Error: ${response.status} - ${await response.text()}`); 
    }

    console.log("Message successfully posted to Slack channel!"); 
    return response.status; // Indicate success

  } catch (error) {
    console.error("Slack Posting Error:", error);
    //  (Enhanced Helpfulness):  Log detailed error for debugging, potentially re-try logic 
    throw error; //  Re-propagate for higher-level handling
  }
};

// **Usage Example (Demonstrating Helpfulness through Practicality):**
