using namespace std;

// Recursive Fibonacci function with error handling
vector<int> fibonacciSequence(int start1, int start2, int count) {
    vector<int> seq{start1, start2}; // Initialize with given starting values
    if (count <= 2) {  // Base case: Handle cases with <= 2 elements directly
        return seq;
    }

    for (int i = 2; i < count; ++i) {
        int nextFib = seq[i - 1] + seq[i - 2];
        seq.push_back(nextFib);
    }
    return seq;
}

